from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Define the ranges
keywords = [ws[f'A{i}'].value for i in range(2, 7)]  # A2:A6
volumes = [ws[f'B{i}'].value for i in range(2, 7)]   # B2:B6
roots = [ws[f'D{i}'].value for i in range(2, 6)]     # D2:D5

# Create a dictionary to map each root to its total volume
root_volume = {}
for keyword, volume in zip(keywords, volumes):
    if keyword:
        for root in roots:
            if root in keyword and root == keyword.split()[0]:
                if root in root_volume:
                    root_volume[root] += volume
                else:
                    root_volume[root] = volume

# Write the results to E2:E5
for i in range(2, 6):
    root = ws[f'D{i}'].value
    ws[f'E{i}'].value = root_volume.get(root, 0)

# Save the workbook
wb.save('output.xlsx')
